SET NAMES utf8mb4;
CREATE TABLE roles (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(30) UNIQUE NOT NULL) ENGINE=InnoDB;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY,role_id INT NOT NULL,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,contact_preference ENUM('email','phone') NOT NULL DEFAULT 'email',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_user_role FOREIGN KEY(role_id) REFERENCES roles(id)) ENGINE=InnoDB;
CREATE TABLE lesson_credits (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL,total_minutes INT NOT NULL DEFAULT 0,remaining_minutes INT NOT NULL DEFAULT 0,CONSTRAINT fk_credit_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE availability (id INT AUTO_INCREMENT PRIMARY KEY,instructor_id INT NOT NULL,start_at DATETIME NOT NULL,end_at DATETIME NOT NULL,type ENUM('available','blocked') NOT NULL DEFAULT 'available',CONSTRAINT fk_availability_instructor FOREIGN KEY(instructor_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_availability(instructor_id,start_at,end_at)) ENGINE=InnoDB;
CREATE TABLE lessons (id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,instructor_id INT NOT NULL,start_at DATETIME NOT NULL,end_at DATETIME NOT NULL,status ENUM('requested','confirmed','completed','cancelled') NOT NULL DEFAULT 'requested',start_location VARCHAR(255) NULL,end_location VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_lesson_student FOREIGN KEY(student_id) REFERENCES users(id),CONSTRAINT fk_lesson_instructor FOREIGN KEY(instructor_id) REFERENCES users(id),INDEX idx_instructor_time(instructor_id,start_at,end_at),INDEX idx_student_time(student_id,start_at)) ENGINE=InnoDB;
CREATE TABLE progress (id INT AUTO_INCREMENT PRIMARY KEY,lesson_id INT NOT NULL,learning_goal VARCHAR(255) NOT NULL,note TEXT NULL,CONSTRAINT fk_progress_lesson FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE) ENGINE=InnoDB;
INSERT INTO roles(name) VALUES ('student'),('instructor');
